 using System.Drawing.Design;
 using System.Windows.Forms;
 using System.Windows.Forms.Design;

 static class Program
 {
     [STAThread]
     static void Main()
     {
         ApplicationConfiguration.Initialize();

         var form = new Form();

         // .NET 9 breaking change: StatusStrip default renderer changed.
         // Explicitly set RenderMode to preserve .NET 8 appearance.
         var statusStrip = new StatusStrip();
         statusStrip.RenderMode = ToolStripRenderMode.System;
         form.Controls.Add(statusStrip);

         Application.Run(form);
     }
 }

 /// <summary>
 /// Wrapper that guards against passing null to DropDownControl,
 /// which is no longer allowed in .NET 9 (nullability annotation change).
 /// </summary>
 static class EditorServiceExtensions
 {
     public static void SafeDropDownControl(
         this IWindowsFormsEditorService service, Control? control)
     {
         if (control is null)
             return;

         service.DropDownControl(control);
     }
 }

